CREATE TABLE IF NOT EXISTS benefit_election (
    tenant_id                tenant_ref   NOT NULL REFERENCES tenant (tenant_id),
    election_id              uuid         NOT NULL,
    election_key             semantic_key NOT NULL,
    worker_ref               text NOT NULL,
    plan_ref                 text NOT NULL,
    coverage_level           text NOT NULL,
    status                   text NOT NULL DEFAULT 'ACTIVE',
    effective_from           date         NOT NULL,
    known_at                 timestamptz  NOT NULL,
    recorded_at              timestamptz  NOT NULL DEFAULT now(),

    PRIMARY KEY (tenant_id, election_id),
    CONSTRAINT benefit_election_key_unique UNIQUE (tenant_id, election_key),
    CONSTRAINT benefit_election_status_check CHECK (status IN ('ACTIVE', 'WAIVED', 'PENDING', 'TERMINATED')),
    CONSTRAINT benefit_election_knowledge_order CHECK (known_at <= recorded_at)
);

CREATE INDEX IF NOT EXISTS benefit_election_recorded
    ON benefit_election (tenant_id, recorded_at DESC);

ALTER TABLE benefit_election ENABLE ROW LEVEL SECURITY;
ALTER TABLE benefit_election FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON benefit_election
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
GRANT SELECT, INSERT, UPDATE ON benefit_election TO hcmnext_app;

CREATE TABLE IF NOT EXISTS benefit_election_revision (
    tenant_id                tenant_ref   NOT NULL REFERENCES tenant (tenant_id),
    revision_id              uuid         NOT NULL,
    election_id              uuid         NOT NULL,
    revision_sequence        bigint       NOT NULL,
    premium_amount           numeric(14,2) NOT NULL,
    currency                 char(3) NOT NULL,
    covered_dependent_count  integer NOT NULL DEFAULT 0,
    known_at                 timestamptz  NOT NULL,
    recorded_at              timestamptz  NOT NULL DEFAULT now(),

    PRIMARY KEY (tenant_id, revision_id),
    CONSTRAINT benefit_election_revision_revision_positive CHECK (revision_sequence >= 1),
    CONSTRAINT benefit_election_revision_currency_check CHECK (currency ~ '^[A-Z]{3}$'),
    CONSTRAINT benefit_election_revision_covered_dependent_count_check CHECK (covered_dependent_count >= 0),
    CONSTRAINT benefit_election_revision_knowledge_order CHECK (known_at <= recorded_at),
    FOREIGN KEY (tenant_id, election_id) REFERENCES benefit_election (tenant_id, election_id)
);

CREATE INDEX IF NOT EXISTS benefit_election_revision_recorded
    ON benefit_election_revision (tenant_id, recorded_at DESC);

CREATE OR REPLACE TRIGGER benefit_election_revision_append_only
    BEFORE UPDATE OR DELETE ON benefit_election_revision
    FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

REVOKE UPDATE, DELETE ON benefit_election_revision FROM PUBLIC;

ALTER TABLE benefit_election_revision ENABLE ROW LEVEL SECURITY;
ALTER TABLE benefit_election_revision FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON benefit_election_revision
    USING (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid)
    WITH CHECK (tenant_id = NULLIF(current_setting('app.tenant_id', true), '')::uuid);
GRANT SELECT, INSERT ON benefit_election_revision TO hcmnext_app;

